        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      if |currentConstrainedOut| < minSpanLen {
        // Span is too short: penalise EOS heavily to force extension.
        var eosTokens := [eosToken];
        var next := helpers.PenalizedConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          eosTokens, -8.0, eosToken
        );
        steps := steps + 1;
        if next == eosToken {
          // EOS despite penalty (only valid token): close if budget allows.
